class Solution:

	def characterReplacement(self, S, k):
		i = 0
		j = 0
		char_dict = {}
		longest_substring = 0
		while j < len(S):
			char_dict[S[j]] = char_dict.get(S[j], 0) + 1
			while max(char_dict.values()) + k < j - i + 1:
				char_dict[S[i]] -= 1
				i += 1
			longest_substring = max(longest_substring, j - i + 1)
			j += 1
		return longest_substring
